#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Sign a throwaway text the way git signs a commit, at the start of a run while the owner is
# there. A locked signer otherwise shows at the first task commit, after the owner left: an
# executor could not commit and had to be replaced (urbanexteriors plan 001), and the gate fix and
# the merge waited in liliiachaika plan 033 (1Password "failed to fill whole buffer").
# Prints "SIGN OK" or "SIGN FAILED: <reason>".
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1

mkdir -p .scratch/tmp
# No extension: ssh-keygen appends `.sig`, 1Password's op-ssh-sign replaces the extension, and
# both then write `sign-probe.sig`.
data=.scratch/tmp/sign-probe
printf 'orca sign probe\n' > "$data"
rm -f "$data.sig"
# Only the first line of a signer's error: some print the key file they were given.
fail() { echo "SIGN FAILED: $(printf '%s\n' "$1" | grep -v -e 'PRIVATE KEY' -e '^$' | head -n 1)"; exit 1; }
format=$(git config --get gpg.format || echo openpgp)
key=$(git config --get user.signingkey || true)

case "$format" in
  ssh)
    program=$(git config --get gpg.ssh.program || echo ssh-keygen)
    [ -n "$key" ] || fail "user.signingkey is not set"
    # A literal public key (as 1Password sets it) is signed through the agent, as git does.
    if [[ "$key" == ssh-* || "$key" == key::* ]]; then
      printf '%s\n' "${key#key::}" > .scratch/tmp/sign-probe.pub
      out=$("$program" -Y sign -n git -f .scratch/tmp/sign-probe.pub -U "$data" 2>&1)
    else
      out=$("$program" -Y sign -n git -f "$key" "$data" 2>&1)
    fi
    code=$?
    [ "$code" -eq 0 ] && [ -s "$data.sig" ] || fail "${out:-exit $code}" ;;
  openpgp|x509)
    program=$(git config --get "gpg.$format.program" || git config --get gpg.program || echo gpg)
    out=$("$program" --batch --yes --detach-sign ${key:+--local-user "$key"} -o "$data.sig" "$data" 2>&1)
    code=$?
    [ "$code" -eq 0 ] && [ -s "$data.sig" ] || fail "${out:-exit $code}" ;;
  *)
    fail "gpg.format $format is unknown" ;;
esac
rm -f "$data.sig" .scratch/tmp/sign-probe.pub
echo "SIGN OK"
